sys_script_fix.script:
// Create the UI Policy record
var policy = new GlideRecord('sys_ui_policy');
policy.initialize();
policy.short_description = 'Show Cisco CSA fields';        // Label for the UI Policy
policy.table = 'change_request';                       // Apply to Change Request table
policy.active = true;                                  // Activate the policy
policy.reverse_if_false = true;                        // Revert actions when condition is false
policy.on_load = true;                                 // Evaluate on form load
policy.conditions = 'category=CSA Configuration';   // Condition: Category is "Cisco secure access"
policy.insert();

// Create UI Policy Action for u_destination_address
var action1 = new GlideRecord('sys_ui_policy_action');
action1.initialize();
action1.ui_policy = policy.sys_id;            // Associate with the above policy
action1.field = 'u_destination_address'; // Target field on the form
action1.visible = 'true';                     // Show the field when condition is met
action1.mandatory = 'true';                   // Make it mandatory
action1.disabled = 'false';                   // Not read-only (leave writable)
action1.insert();

// Create UI Policy Action for u_destination_list
var action2 = new GlideRecord('sys_ui_policy_action');
action2.initialize();
action2.ui_policy = policy.sys_id;
action2.field = 'u_destination_list';
action2.visible = 'true';
action2.mandatory = 'true';
action2.disabled = 'false';
action2.insert();
